driverRow = Row([actionCard, sourceCard])
actionCard = Card("Week 4 retention by week-0 action", [Bars(["Connected a data source", "Invited a teammate", "Created a project", "Built a dashboard", "None of these"], [Series("Week 4", [41.2, 38.5, 34.0, 44.6, 12.8], [38.9, 36.1, 31.7, 42.0, 12.1])], "percent", "horizontal")], "half", "All plans · first 7 days after creation")
