weekCols = {"8w": ["W0", "W1", "W2", "W3", "W4", "W5", "W6", "W7"], "12w": ["W0", "W1", "W2", "W3", "W4", "W5", "W6", "W7", "W8", "W9", "W10", "W11"]}
